package pe.siniestrofacil.application.service;
import pe.siniestrofacil.application.dto.CrearSiniestroRequest; import pe.siniestrofacil.domain.model.Siniestro; import pe.siniestrofacil.domain.port.SiniestroRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class SiniestroService { private final SiniestroRepository repository; public SiniestroService(SiniestroRepository repository){this.repository=repository;} @Transactional public Siniestro create(CrearSiniestroRequest r){Siniestro draft=new Siniestro(null,null,null,r.fecha(),r.ubicacionAproximada(),r.tipoEvento(),r.danosAparentes(),Siniestro.REPORTADO); return repository.createByBusinessKeys(r.poliza().numero(),r.vehiculo().placa(),draft,r.reportante());} public Optional<Siniestro> findById(long id){return repository.findById(id);} public List<Siniestro> findAll(){return repository.findAll();} @Transactional public void transition(long id,String state){repository.transition(id,state);} }